// Sem0 — Build Prompt (product_kind / product_family / attr_profile).
// Policy v2: vitamin_or_baa + medical_device (hygiene_like | clinical_like).
// No category_id / direction / need. Soft-continue into Sem1.

const DRUG_FAMILIES = [
  'кожные заболевания',
  'простуда и ОРВИ',
  'ЖКТ',
  'Кровь / Кровеносная система',
  'Нервная система',
  'Боль и Температура',
  'Сердце и сосуды',
  'Опорно-двигательный аппарат',
  'Кашель',
  'Урология',
  'Слух и зрение',
  'Гормоны',
  'Стоматология',
  'Бактериофаги',
  'Противоклещевые',
  'Инъекции',
  'Инфузии',
  'Гомеопатия',
  'Травы',
];

const DEVICE_FAMILIES = [
  'Измерительные приборы',
  'Гигиена и косметика',
  'Товары для мам и детей',
  'Приборы для терапии',
  'Приборы и средства для инъекций',
  'Перевязочные материалы',
  'Пластыри',
  'Другое медизделие',
];

return items.map((item, index) => {
  const j = item.json || {};
  const shortlist = Array.isArray(j.shortlist_json) ? j.shortlist_json : [];

  const shortlistHint = shortlist.length
    ? shortlist
        .slice(0, 5)
        .map((c, idx) => {
          const name = c.category_name || c.name || '';
          const code = c.category_code || c.code || '';
          return `${idx + 1}. code=${code}, name=${name}`;
        })
        .join('\n')
    : 'NONE';

  const attrHints = {
    norm_mnn_product: j.norm_mnn_product ?? null,
    norm_brand_guess: j.norm_brand_guess ?? null,
    norm_form_guess: j.norm_form_guess ?? null,
    norm_dosage_guess: j.norm_dosage_guess ?? null,
    norm_pack_size_guess: j.norm_pack_size_guess ?? null,
    norm_product_type_guess: j.norm_product_type_guess ?? j.product_type_guess ?? null,
  };

  const promptSystem =
    'You analyze a pharmacy product and determine its top-level kind, therapeutic or usage family, and which semantic attributes are applicable.\n\n' +
    'Return ONLY valid JSON with keys:\n' +
    'product_kind, product_family, attr_profile, confidence, explanation.\n\n' +
    'Do NOT return category_id, direction, need, block_family, or any leaf category.\n\n' +
    'product_kind must be one of: drug, vitamin_or_baa, medical_device, cosmetic_hygiene, other.\n' +
    'attr_profile must contain all keys mnn, brand, rx_otc, nosology, administration_route, dosage_form, dosage, age_segment, package_hint, combination_hint with values "applicable" or "not_applicable".\n\n' +
    '=== vitamin_or_baa ===\n' +
    'attr_profile: mnn, brand, nosology, administration_route, dosage_form, dosage, age_segment, package_hint, combination_hint = applicable; rx_otc = not_applicable.\n' +
    'Sem1 will fill values; you only mark applicability. Allowed later meanings:\n' +
    '- vitamins: nosology in {отдельные нутриенты, комплексные профили}; mnn may be vitamin/nutrient (B1, B6, B9, фолиевая кислота, B12, D, A, E, K, …) or "Комплекс".\n' +
    '- BAA: nosology in {нутрицевтики, парафармацевтики, эубиотики}; mnn null if no clear nutrient.\n\n' +
    '=== medical_device ===\n' +
    'Choose product_family from the device list. Split into two profiles via family:\n' +
    '- hygiene_like (Гигиена и косметика; Товары для мам и детей): mnn, rx_otc, nosology, administration_route, dosage_form, dosage, combination_hint = not_applicable; brand, age_segment, package_hint = applicable.\n' +
    '- clinical_like (Пластыри; Перевязочные материалы; Приборы и средства для инъекций; Приборы для терапии; Измерительные приборы; Другое медизделие when clinically useful): mnn, rx_otc, nosology, combination_hint = not_applicable; brand, administration_route, dosage_form, dosage, age_segment, package_hint = applicable.\n\n' +
    '=== cosmetic_hygiene ===\n' +
    'Same attr_profile as medical_device hygiene_like.\n\n' +
    '=== drug ===\n' +
    'Pharma attrs usually applicable.\n\n' +
    '=== other ===\n' +
    'Prefer conservative not_applicable for mnn/rx_otc/nosology unless clearly needed; brand/package/age often applicable.\n\n' +
    'confidence must be a number from 0.0 to 1.0.\n' +
    'explanation must be a short Russian string (1–3 sentences).';

  const promptUser = `
Товар (normalized_text):
${j.normalized_text || j.combined_text || ''}

Подсказки после Norm (могут быть null):
${JSON.stringify(attrHints, null, 2)}

Мягкая подсказка Stage 1 shortlist (НЕ обязательный набор):
${shortlistHint}

normalize_meta:
${JSON.stringify(j.normalize_meta || {}, null, 2)}

Списки product_family:
- если product_kind=drug, выбери один из: ${DRUG_FAMILIES.join('; ')}
- если product_kind=medical_device, выбери один из: ${DEVICE_FAMILIES.join('; ')}
- если product_kind=vitamin_or_baa: свободный короткий текст или null
- иначе: null

Задача:
- Определи product_kind.
- Определи product_family по правилам выше (или null).
- Заполни attr_profile строго по policy выше (vitamin_or_baa / medical_device hygiene_like|clinical_like / cosmetic_hygiene / drug / other).
- Для vitamin_or_baa НЕ ставь mnn и nosology в not_applicable — они applicable (rx_otc = not_applicable).
- Для medical_device clinical_like разреши administration_route / dosage_form / dosage.
- Верни только JSON без markdown.
`.trim();

  return {
    json: {
      ...j,
      prompt_system: promptSystem,
      prompt_user: promptUser,
      llm_prompt_debug: {
        system: promptSystem,
        user: promptUser,
        stage: 'sem0',
      },
    },
    pairedItem: index,
  };
});

// Sem0 — LLM Prepare (product_kind_select).

function withoutStaleLlmOutput(j) {
  const src = j || {};
  const {
    output,
    text,
    response,
    content,
    result,
    llm_raw_output_text,
    ...rest
  } = src;
  return rest;
}

return items.map((item, index) => {
  const j = withoutStaleLlmOutput(item.json);
  const WORKFLOW_VERSION = 'stage2_hierarchy_v1';
  const PROMPT_VERSION = 'prompt_sem0_v2';
  const C = j.constants || {};

  return {
    json: {
      ...j,
      workflow_version: WORKFLOW_VERSION,
      prompt_version: PROMPT_VERSION,
      stage: 'product_kind_select',
      actor_type: (C.actor_type && C.actor_type.llm) || 'llm',
      actor_name:
        (C.model && C.model.cascade_actor_name) ||
        (C.model && C.model.primary_actor_name) ||
        'deepseek-chat',
      context: {
        run_id:
          j.run_id !== undefined && j.run_id !== null && j.run_id !== ''
            ? Number(j.run_id)
            : null,
        product_id:
          j.product_id !== undefined && j.product_id !== null && j.product_id !== ''
            ? Number(j.product_id)
            : null,
        product_raw_id:
          j.product_raw_id !== undefined && j.product_raw_id !== null && j.product_raw_id !== ''
            ? Number(j.product_raw_id)
            : null,
        normalized_text: j.normalized_text ?? null,
        normalize_meta: j.normalize_meta ?? null,
        norm_warnings: j.norm_warnings ?? [],
        shortlist_json: Array.isArray(j.shortlist_json) ? j.shortlist_json : [],
      },
      prompt_system: j.prompt_system || '',
      prompt_user: j.prompt_user || '',
    },
    pairedItem: index,
  };
});

// Sem0 — Post-process (product_kind / attr_profile). Policy v2.
// Soft-continue always into Sem1. On failure: product_kind=other, all attrs applicable.

function extractJsonString(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object') return JSON.stringify(value);
  let text = String(value).trim();
  const codeFenceMatch = text.match(/^```(?:json)?\s*\n?([\s\S]+?)\n?```\s*$/i);
  if (codeFenceMatch) text = codeFenceMatch[1].trim();
  return text;
}

function safeParseJson(value) {
  const text = extractJsonString(value);
  if (!text) return { ok: false, error: 'empty_output', parsed: null, raw_text: null };
  try {
    return { ok: true, error: null, parsed: JSON.parse(text), raw_text: text };
  } catch (e) {
    return { ok: false, error: 'invalid_json', parsed: null, raw_text: text };
  }
}

function normalizeConfidence(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  if (n < 0 || n > 1) return null;
  return n;
}

function safeText(v) {
  if (v === undefined || v === null || v === '') return null;
  const s = String(v).trim();
  return s === '' ? null : s;
}

function pickLlmRaw(root) {
  if (root.output !== undefined) return root.output;
  if (root.text !== undefined) return root.text;
  if (root.response !== undefined) return root.response;
  if (root.content !== undefined) return root.content;
  if (root.result !== undefined) return root.result;
  return null;
}

const ATTR_KEYS = [
  'mnn',
  'brand',
  'rx_otc',
  'nosology',
  'administration_route',
  'dosage_form',
  'dosage',
  'age_segment',
  'package_hint',
  'combination_hint',
];

const KIND_ALLOWED = new Set([
  'drug',
  'vitamin_or_baa',
  'medical_device',
  'cosmetic_hygiene',
  'other',
]);

const DEVICE_HYGIENE_FAMILIES = new Set(['Гигиена и косметика', 'Товары для мам и детей']);

const DEVICE_CLINICAL_FAMILIES = new Set([
  'Измерительные приборы',
  'Приборы для терапии',
  'Приборы и средства для инъекций',
  'Перевязочные материалы',
  'Пластыри',
  'Другое медизделие',
]);

const STAGE = 'product_kind_select';

function allApplicableProfile() {
  const out = {};
  for (const k of ATTR_KEYS) out[k] = 'applicable';
  return out;
}

function normalizeAttrProfile(raw) {
  const src = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  const out = {};
  for (const k of ATTR_KEYS) {
    const v = String(src[k] || '').trim().toLowerCase();
    out[k] = v === 'not_applicable' ? 'not_applicable' : 'applicable';
  }
  return out;
}

function profileFromSpec(spec) {
  const out = {};
  for (const k of ATTR_KEYS) {
    out[k] = spec[k] === 'not_applicable' ? 'not_applicable' : 'applicable';
  }
  return out;
}

function classifyMedicalDeviceProfile(family) {
  const f = safeText(family);
  if (!f) return null;
  if (DEVICE_HYGIENE_FAMILIES.has(f)) return 'hygiene_like';
  if (DEVICE_CLINICAL_FAMILIES.has(f)) return 'clinical_like';
  return null;
}

function applyPolicyOverlay(kind, family, rawProfile) {
  const base = normalizeAttrProfile(rawProfile);
  let medicalDeviceProfile = null;
  let productKindGroupHint = kind;

  if (kind === 'vitamin_or_baa') {
    return {
      attrProfile: profileFromSpec({
        mnn: 'applicable',
        brand: 'applicable',
        rx_otc: 'not_applicable',
        nosology: 'applicable',
        administration_route: 'applicable',
        dosage_form: 'applicable',
        dosage: 'applicable',
        age_segment: 'applicable',
        package_hint: 'applicable',
        combination_hint: 'applicable',
      }),
      medicalDeviceProfile: null,
      productKindGroupHint: 'vitamin_or_baa',
    };
  }

  if (kind === 'cosmetic_hygiene') {
    return {
      attrProfile: profileFromSpec({
        mnn: 'not_applicable',
        brand: 'applicable',
        rx_otc: 'not_applicable',
        nosology: 'not_applicable',
        administration_route: 'not_applicable',
        dosage_form: 'not_applicable',
        dosage: 'not_applicable',
        age_segment: 'applicable',
        package_hint: 'applicable',
        combination_hint: 'not_applicable',
      }),
      medicalDeviceProfile: null,
      productKindGroupHint: 'cosmetic_hygiene',
    };
  }

  if (kind === 'medical_device') {
    medicalDeviceProfile = classifyMedicalDeviceProfile(family);
    // Fallback: if family unknown, prefer clinical_like when route/form marked applicable by model.
    if (!medicalDeviceProfile) {
      const clinicalSignal =
        base.administration_route === 'applicable' ||
        base.dosage_form === 'applicable' ||
        base.dosage === 'applicable';
      medicalDeviceProfile = clinicalSignal ? 'clinical_like' : 'hygiene_like';
    }
    productKindGroupHint = `medical_device:${medicalDeviceProfile}`;
    if (medicalDeviceProfile === 'hygiene_like') {
      return {
        attrProfile: profileFromSpec({
          mnn: 'not_applicable',
          brand: 'applicable',
          rx_otc: 'not_applicable',
          nosology: 'not_applicable',
          administration_route: 'not_applicable',
          dosage_form: 'not_applicable',
          dosage: 'not_applicable',
          age_segment: 'applicable',
          package_hint: 'applicable',
          combination_hint: 'not_applicable',
        }),
        medicalDeviceProfile,
        productKindGroupHint,
      };
    }
    return {
      attrProfile: profileFromSpec({
        mnn: 'not_applicable',
        brand: 'applicable',
        rx_otc: 'not_applicable',
        nosology: 'not_applicable',
        administration_route: 'applicable',
        dosage_form: 'applicable',
        dosage: 'applicable',
        age_segment: 'applicable',
        package_hint: 'applicable',
        combination_hint: 'not_applicable',
      }),
      medicalDeviceProfile,
      productKindGroupHint,
    };
  }

  if (kind === 'drug') {
    return {
      attrProfile: base,
      medicalDeviceProfile: null,
      productKindGroupHint: 'drug',
    };
  }

  // other: keep model profile (soft), after normalize
  return {
    attrProfile: base,
    medicalDeviceProfile: null,
    productKindGroupHint: 'other',
  };
}

return items.map((item, index) => {
  const root = item.json || {};
  const C = root.constants || {};
  const ACTOR_LLM = (C.actor_type && C.actor_type.llm) || 'llm';
  const MODEL_NAME =
    (C.model && C.model.cascade_actor_name) ||
    (C.model && C.model.primary_actor_name) ||
    'deepseek-chat';

  const raw = pickLlmRaw(root);
  const parsed = safeParseJson(raw);

  let validationPassed = false;
  let rejectReason = null;
  let productKind = 'other';
  let productFamily = null;
  let attrProfile = allApplicableProfile();
  let medicalDeviceProfile = null;
  let productKindGroupHint = 'other';
  let confidence = null;
  let explanation = null;

  if (!parsed.ok) {
    rejectReason = parsed.error || 'empty_output';
  } else if (!parsed.parsed || typeof parsed.parsed !== 'object' || Array.isArray(parsed.parsed)) {
    rejectReason = 'invalid_shape';
  } else {
    const obj = parsed.parsed;
    if (obj.category_id !== undefined && obj.category_id !== null && String(obj.category_id).trim() !== '') {
      rejectReason = 'category_id_forbidden';
    } else if (obj.direction !== undefined && obj.direction !== null && String(obj.direction).trim() !== '') {
      rejectReason = 'direction_forbidden';
    } else if (obj.need !== undefined && obj.need !== null && String(obj.need).trim() !== '') {
      rejectReason = 'need_forbidden';
    } else {
      const kind = safeText(obj.product_kind);
      const conf = normalizeConfidence(obj.confidence);
      const expl = safeText(obj.explanation);
      if (!kind || !KIND_ALLOWED.has(kind)) {
        rejectReason = 'invalid_product_kind';
      } else if (conf === null) {
        rejectReason = 'invalid_confidence';
      } else if (expl === null) {
        rejectReason = 'missing_explanation';
        productKind = kind;
        productFamily = safeText(obj.product_family);
        const overlay = applyPolicyOverlay(kind, productFamily, obj.attr_profile);
        attrProfile = overlay.attrProfile;
        medicalDeviceProfile = overlay.medicalDeviceProfile;
        productKindGroupHint = overlay.productKindGroupHint;
        confidence = conf;
      } else {
        productKind = kind;
        productFamily = safeText(obj.product_family);
        const overlay = applyPolicyOverlay(kind, productFamily, obj.attr_profile);
        attrProfile = overlay.attrProfile;
        medicalDeviceProfile = overlay.medicalDeviceProfile;
        productKindGroupHint = overlay.productKindGroupHint;
        confidence = conf;
        explanation = expl;
        validationPassed = true;
        rejectReason = null;
      }
    }
  }

  // Soft-fail: other + all applicable (do not regress drugs when Sem0 breaks).
  if (!validationPassed && rejectReason && rejectReason !== 'missing_explanation') {
    productKind = 'other';
    productFamily = null;
    attrProfile = allApplicableProfile();
    medicalDeviceProfile = null;
    productKindGroupHint = 'other';
  }

  const prevTrace =
    root.cascade_trace && typeof root.cascade_trace === 'object' && !Array.isArray(root.cascade_trace)
      ? root.cascade_trace
      : {};
  const path = Array.isArray(prevTrace.path) ? [...prevTrace.path] : [];
  if (!path.includes(STAGE)) path.push(STAGE);
  const stages = Array.isArray(prevTrace.stages) ? [...prevTrace.stages] : [];
  stages.push({
    stage: STAGE,
    actor_type: ACTOR_LLM,
    actor_name: MODEL_NAME,
    validation_passed: validationPassed,
    reject_reason: rejectReason,
    notes: 'sem0_v2',
  });

  const {
    output,
    text,
    response,
    content,
    result,
    llm_raw_output_text,
    prompt_system,
    prompt_user,
    llm_prompt_debug,
    ...rest
  } = root;

  return {
    json: {
      ...rest,
      workflow_version: root.workflow_version || 'stage2_hierarchy_v1',
      prompt_version: 'prompt_sem0_v2',
      stage: STAGE,
      actor_type: ACTOR_LLM,
      actor_name: MODEL_NAME,
      product_kind: productKind,
      product_family: productFamily,
      attr_profile: attrProfile,
      medical_device_profile: medicalDeviceProfile,
      product_kind_group_hint: productKindGroupHint,
      sem0_confidence: confidence,
      sem0_explanation: explanation,
      sem0_validation_passed: validationPassed,
      sem0_reject_reason: rejectReason,
      sem0_raw_json: parsed.raw_text
        ? { raw_text: parsed.raw_text, parsed: parsed.parsed }
        : raw !== null && raw !== undefined
          ? { raw: raw }
          : null,
      selected_category_id: null,
      cascade_trace: {
        ...prevTrace,
        path,
        stages,
      },
    },
    pairedItem: index,
  };
});

// Sem — Build Prompt (hierarchy B3 Sem / semantic_primary v3).
// Uses Sem0 product_kind / product_family / attr_profile hints (policy v2).
// No category_id / direction / need selection.

return items.map((item, index) => {
  const j = item.json || {};
  const shortlist = Array.isArray(j.shortlist_json) ? j.shortlist_json : [];

  const shortlistHint = shortlist.length
    ? shortlist
        .slice(0, 5)
        .map((c, idx) => {
          const name = c.category_name || c.name || '';
          const code = c.category_code || c.code || '';
          return `${idx + 1}. code=${code}, name=${name}`;
        })
        .join('\n')
    : 'NONE';

  const attrHints = {
    norm_mnn_product: j.norm_mnn_product ?? null,
    norm_brand_guess: j.norm_brand_guess ?? null,
    norm_form_guess: j.norm_form_guess ?? null,
    norm_dosage_guess: j.norm_dosage_guess ?? null,
    norm_pack_size_guess: j.norm_pack_size_guess ?? null,
    norm_product_type_guess: j.norm_product_type_guess ?? j.product_type_guess ?? null,
    product_kind: j.product_kind ?? null,
    product_family: j.product_family ?? null,
    attr_profile: j.attr_profile ?? null,
    medical_device_profile: j.medical_device_profile ?? null,
    product_kind_group_hint: j.product_kind_group_hint ?? null,
  };

  const promptSystem =
    'You extract semantic attributes for a pharmacy product. Return ONLY valid JSON with keys: mnn, brand, rx_otc, nosology, administration_route, dosage_form, dosage, age_segment, package_hint, combination_hint, confidence, explanation. Do NOT return category_id, direction, need, block_family, or any final leaf category. All attribute fields may be null. confidence must be a number from 0.0 to 1.0. explanation must be a short Russian string (1–3 sentences).\n\n' +
    'Учитывай product_kind / attr_profile из подсказок:\n' +
    '- Если attr_profile[key]="not_applicable" — верни null для этого ключа.\n' +
    '- drug: pharma attrs допустимы при наличии сигнала.\n' +
    '- vitamin_or_baa:\n' +
    '  - можно заполнять mnn, nosology, administration_route, dosage_form, dosage, age_segment, package_hint, combination_hint, brand;\n' +
    '  - rx_otc всегда null;\n' +
    '  - витамины: nosology ∈ {отдельные нутриенты, комплексные профили}; mnn = витамин/нутриент (B1, B6, фолиевая кислота, D, …) или "Комплекс";\n' +
    '  - БАД: nosology ∈ {нутрицевтики, парафармацевтики, эубиотики}; mnn может быть null.\n' +
    '- medical_device:\n' +
    '  - mnn, rx_otc, nosology, combination_hint обычно null;\n' +
    '  - administration_route / dosage_form / dosage — только если attr_profile разрешает (clinical_like);\n' +
    '  - hygiene_like: только brand / age_segment / package_hint.\n' +
    '- cosmetic_hygiene: только brand / age_segment / package_hint; остальные pharma-поля null.\n' +
    '- other: следуй attr_profile; не выдумывай.\n' +
    '- В explanation кратко укажи kind и почему часть полей не применима, если это так.';

  const promptUser = `
Товар (normalized_text):
${j.normalized_text || j.combined_text || ''}

Подсказки после Norm / Sem0 (могут быть null):
${JSON.stringify(attrHints, null, 2)}

Мягкая подсказка Stage 1 shortlist (НЕ обязательный набор, НЕ выбирай category_id):
${shortlistHint}

normalize_meta:
${JSON.stringify(j.normalize_meta || {}, null, 2)}

Задача:
- Извлеки семантические атрибуты с учётом product_kind / attr_profile.
- НЕ выбирай category_id / направление / потребность / финальную категорию.
- Если признак неизвестен или not_applicable — верни null (не выдумывай).
- confidence: 0.0–1.0; explanation: 1–3 предложения на русском.
- Верни только JSON без markdown.
`.trim();

  return {
    json: {
      ...j,
      prompt_system: promptSystem,
      prompt_user: promptUser,
      llm_prompt_debug: {
        system: promptSystem,
        user: promptUser,
      },
    },
    pairedItem: index,
  };
});

// Sem — LLM Prepare (hierarchy B3 Sem).

function withoutStaleLlmOutput(j) {
  const src = j || {};
  const {
    output,
    text,
    response,
    content,
    result,
    llm_raw_output_text,
    ...rest
  } = src;
  return rest;
}

return items.map((item, index) => {
  const j = withoutStaleLlmOutput(item.json);
  const WORKFLOW_VERSION = 'stage2_hierarchy_v1';
  const PROMPT_VERSION = 'prompt_semantic_v3';
  const C = j.constants || {};

  return {
    json: {
      ...j,
      workflow_version: WORKFLOW_VERSION,
      prompt_version: PROMPT_VERSION,
      stage: (C.stage && C.stage.semantic_primary) || 'semantic_primary',
