});

const run = $('Run — Create Run').first().json;
if (!run?.id) {
  throw new Error('Run — Create Run did not return classification_runs.id');
}
// B2 skeleton: always emit one closer item; cascade/LLM path is disconnected.
return [{
  json: {
    id: Number(run.id),
    skeleton_empty: true,
    product_count: items.length
  }
}];

const body = $input.first().json.body || $input.first().json || {};
const batchRaw = Number(body.batch_size);
const batchSize = Number.isFinite(batchRaw) && batchRaw > 0
  ? Math.min(Math.trunc(batchRaw), 10)
  : 5;

return [{
  json: {
    trigger: 'webhook',
    batch_size: batchSize
  }
